import React,{useState} from 'react';
export default function Capacity({state='ready'}){const [period,setPeriod]=useState('Monthly');if(state!=='ready')return <section className="state" data-state={state} role={state==='error'?'alert':'status'}><h2>{state==='loading'?'Loading context…':state==='empty'?'Nothing to show yet':'This view needs attention'}</h2><p>{state==='error'?'Refresh the authorized data source and try again.':'The workspace remains available.'}</p></section>;
const values=period==='Monthly'?[42,68,54,81]:[64,78,92,60];return <div className="shell"><span className="eyebrow">Planning / Reference analytics</span><h1>See the pressure before it becomes a blocker.</h1><p>A custom view for a capacity conversation, not a generated table.</p><div className="row"><button id="quarter" className="btn" onClick={()=>setPeriod('Quarterly')}>Quarterly view</button><button className="btn ghost" onClick={()=>setPeriod('Monthly')}>Monthly view</button><span id="result" className="tag">{period}</span></div><div className="grid"><section className="panel"><span className="eyebrow">Capacity utilization</span><svg viewBox="0 0 420 220" role="img" aria-label="Reference team utilization"><line x1="20" x2="410" y1="190" y2="190" stroke="currentColor" opacity=".2"/>{values.map((v,i)=><g key={i}><rect x={40+i*95} y={190-v*1.6} width="52" height={v*1.6} rx="8" fill="var(--primary)"/><text x={66+i*95} y="210" textAnchor="middle" fill="currentColor">Team {i+1}</text><text x={66+i*95} y={180-v*1.6} textAnchor="middle" fill="currentColor">{v}%</text></g>)}</svg></section><section className="panel soft"><h2>Make room for the important work.</h2><p>The reference values help explore allocation tradeoffs. Bind approved data sources before using this for operational decisions.</p></section></div></div>;}
